  "graphql-federation-practice/java-service/src/main/java/com/techflow/orders/service/OrderService.java": {
    "lang": "java",
    "lines": 113,
    "content": "package com.techflow.orders.service;\n\nimport com.techflow.orders.dto.CreateOrderRequest;\nimport com.techflow.orders.exception.EntityNotFoundException;\nimport com.techflow.orders.model.Order;\nimport com.techflow.orders.model.OrderItem;\nimport com.techflow.orders.model.OrderStatus;\nimport com.techflow.orders.repository.OrderRepository;\nimport io.micrometer.core.instrument.Counter;\nimport io.micrometer.core.instrument.MeterRegistry;\nimport io.micrometer.core.instrument.Timer;\nimport java.time.Instant;\nimport java.util.List;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.slf4j.MDC;\nimport org.springframework.stereotype.Service;\n\n@Service\npublic class OrderService {\n    private static final Logger logger = LoggerFactory.getLogger(OrderService.class);\n\n    private final OrderRepository orderRepository;\n    private final Counter orderCreatedCounter;\n    private final Counter orderRetrievedCounter;\n    private final Timer orderCreationTimer;\n\n    public OrderService(OrderRepository orderRepository, MeterRegistry meterRegistry) {\n        this.orderRepository = orderRepository;\n        this.orderCreatedCounter = Counter.builder(\"orders.created\")\n                .description(\"Total number of orders created\")\n                .register(meterRegistry);\n        this.orderRetrievedCounter = Counter.builder(\"orders.retrieved\")\n                .description(\"Total number of orders retrieved\")\n                .register(meterRegistry);\n        this.orderCreationTimer = Timer.builder(\"orders.creation.time\")\n                .description(\"Time taken to create an order\")\n                .register(meterRegistry);\n    }\n\n    public List<Order> getAllOrders() {\n        String correlationId = MDC.get(\"correlationId\");\n        logger.info(\"Fetching all orders. correlationId={}\", correlationId);\n        orderRetrievedCounter.increment();\n        return orderRepository.findAll();\n    }\n\n    public Order getOrderById(Long id) {\n        String correlationId = MDC.get(\"correlationId\");\n        logger.info(\"Fetching order by id. orderId={}, correlationId={}\", id, correlationId);\n        orderRetrievedCounter.increment();\n        return orderRepository.findById(id)\n                .orElseThrow(() -> new EntityNotFoundException(\"Order not found with id: \" + id));\n    }\n\n    public List<Order> getOrdersByUserId(String userId) {\n        String correlationId = MDC.get(\"correlationId\");\n        logger.info(\"Fetching orders by userId. userId={}, correlationId={}\", userId, correlationId);\n        orderRetrievedCounter.increment();\n        return orderRepository.findByUserId(userId);\n    }\n\n    public Order createOrder(CreateOrderRequest request) {\n        String correlationId = MDC.get(\"correlationId\");\n\n        return orderCreationTimer.record(() -> {\n            logger.info(\"Creating new order. userId={}, correlationId={}\", request.getUserId(), correlationId);\n\n            Order order = new Order();\n            order.setUserId(request.getUserId());\n            order.setStatus(OrderStatus.PENDING);\n            order.setCreatedAt(Instant.now());\n\n            double totalAmount = 0.0;\n            for (var itemRequest : request.getItems()) {\n                OrderItem item = new OrderItem();\n                item.setProductId(itemRequest.getProductId());\n                item.setQuantity(itemRequest.getQuantity());\n                item.setPrice(getMockPrice(itemRequest.getProductId()));\n                order.getItems().add(item);\n                totalAmount += item.getPrice() * item.getQuantity();\n            }\n\n            order.setTotalAmount(totalAmount);\n            Order savedOrder = orderRepository.save(order);\n            orderCreatedCounter.increment();\n            return savedOrder;\n        });\n    }\n\n    public Order updateOrderStatus(Long id, OrderStatus status) {\n        Order order = orderRepository.findById(id)\n                .orElseThrow(() -> new EntityNotFoundException(\"Order not found with id: \" + id));\n        order.setStatus(status);\n        return orderRepository.save(order);\n    }\n\n    public void deleteOrder(Long id) {\n        if (!orderRepository.existsById(id)) {\n            throw new EntityNotFoundException(\"Order not found with id: \" + id);\n        }\n        orderRepository.deleteById(id);\n    }\n\n    private double getMockPrice(String productId) {\n        return switch (productId) {\n            case \"prod-789\" -> 149.99;\n            case \"prod-101\" -> 89.99;\n            case \"prod-202\" -> 199.99;\n            default -> 99.99;\n        };\n    }\n}"
  },
