    "content": "package com.techflow.orders;\n\nimport static org.mockito.ArgumentMatchers.any;\nimport static org.mockito.Mockito.when;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.patch;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.techflow.orders.controller.OrderController;\nimport com.techflow.orders.dto.CreateOrderRequest;\nimport com.techflow.orders.model.Order;\nimport com.techflow.orders.model.OrderStatus;\nimport com.techflow.orders.service.OrderService;\nimport java.util.List;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;\nimport org.springframework.boot.test.mock.mockito.MockBean;\nimport org.springframework.http.MediaType;\nimport org.springframework.test.web.servlet.MockMvc;\n\n@WebMvcTest(OrderController.class)\nclass OrderControllerTest {\n    @Autowired\n    private MockMvc mockMvc;\n\n    @MockBean\n    private OrderService orderService;\n\n    @Test\n    void shouldGetAllOrders() throws Exception {\n        when(orderService.getAllOrders()).thenReturn(List.of());\n        mockMvc.perform(get(\"/api/orders\")).andExpect(status().isOk());\n    }\n\n    @Test\n    void shouldGetOrderById() throws Exception {\n        when(orderService.getOrderById(1L)).thenReturn(new Order());\n        mockMvc.perform(get(\"/api/orders/1\")).andExpect(status().isOk());\n    }\n\n    @Test\n    void shouldCreateOrder() throws Exception {\n        when(orderService.createOrder(any(CreateOrderRequest.class))).thenReturn(new Order());\n\n        mockMvc.perform(post(\"/api/orders\")\n                        .contentType(MediaType.APPLICATION_JSON)\n                        .content(\"\"\"\n                                {\n                                  \"userId\": \"123\",\n                                  \"items\": [\n                                    { \"productId\": \"prod-789\", \"quantity\": 2 }\n                                  ]\n                                }\n                                \"\"\"))\n                .andExpect(status().isCreated());\n    }\n\n    @Test\n    void shouldUpdateOrderStatus() throws Exception {\n        when(orderService.updateOrderStatus(1L, OrderStatus.SHIPPED)).thenReturn(new Order());\n\n        mockMvc.perform(patch(\"/api/orders/1/status\")\n                        .contentType(MediaType.APPLICATION_JSON)\n                        .content(\"{\\\"status\\\":\\\"SHIPPED\\\"}\"))\n                .andExpect(status().isOk());\n    }\n\n    @Test\n    void shouldDeleteOrder() throws Exception {\n        mockMvc.perform(delete(\"/api/orders/1\"))\n                .andExpect(status().isNoContent());\n    }\n}"
