    "content": "import { describe, it, expect, beforeEach } from '@jest/globals';\nimport { resolvers, createShippingInfoLoader, createOrderLoader } from '../src/resolvers/orderResolvers.js';\nimport { OrderDataSource, InventoryDataSource, ShippingDataSource } from '../src/dataSources/orderDataSource.js';\n\ndescribe('Order Resolvers', () => {\n  let dataSources;\n  let loaders;\n  let context;\n\n  beforeEach(() => {\n    dataSources = {\n      orderDataSource: new OrderDataSource(),\n      inventoryDataSource: new InventoryDataSource(),\n      shippingDataSource: new ShippingDataSource()\n    };\n\n    loaders = {\n      shippingInfoLoader: createShippingInfoLoader(dataSources.shippingDataSource),\n      orderLoader: createOrderLoader(dataSources.orderDataSource)\n    };\n\n    context = {\n      dataSources,\n      loaders,\n      correlationId: 'test-correlation-id'\n    };\n  });\n\n  describe('User.orders resolver', () => {\n    it('should return orders for a user', async () => {\n      const user = { id: '123' };\n      const orders = await resolvers.User.orders(user, {}, context);\n\n      expect(orders).toBeDefined();\n      expect(Array.isArray(orders)).toBe(true);\n      expect(orders.length).toBeGreaterThan(0);\n      expect(orders[0]).toHaveProperty('id');\n      expect(orders[0]).toHaveProperty('userId', '123');\n      expect(orders[0]).toHaveProperty('status');\n      expect(orders[0]).toHaveProperty('totalAmount');\n    });\n\n    it('should return empty array for user with no orders', async () => {\n      const user = { id: '999' };\n      const orders = await resolvers.User.orders(user, {}, context);\n\n      expect(orders).toBeDefined();\n      expect(Array.isArray(orders)).toBe(true);\n      expect(orders.length).toBe(0);\n    });\n  });\n\n  describe('Order.shippingInfo resolver', () => {\n    it('should return shipping info for an order', async () => {\n      const order = { id: 'order-456' };\n      const shippingInfo = await resolvers.Order.shippingInfo(order, {}, context);\n\n      expect(shippingInfo).toBeDefined();\n      expect(shippingInfo).toHaveProperty('status');\n      expect(shippingInfo).toHaveProperty('trackingNumber');\n    });\n\n    it('should return null for order without shipping info', async () => {\n      const order = { id: 'order-999' };\n      const shippingInfo = await resolvers.Order.shippingInfo(order, {}, context);\n      expect(shippingInfo).toBeNull();\n    });\n  });\n\n  describe('Query.orders resolver', () => {\n    it('should return orders for a specific user', async () => {\n      const orders = await resolvers.Query.orders({}, { userId: '123' }, context);\n\n      expect(orders).toBeDefined();\n      expect(Array.isArray(orders)).toBe(true);\n      expect(orders.length).toBeGreaterThan(0);\n      expect(orders.every(order => order.userId === '123')).toBe(true);\n    });\n\n    it('should return empty array for user with no orders', async () => {\n      const orders = await resolvers.Query.orders({}, { userId: '999' }, context);\n\n      expect(orders).toBeDefined();\n      expect(Array.isArray(orders)).toBe(true);\n      expect(orders.length).toBe(0);\n    });\n  });\n\n  describe('Mutation.createOrder resolver', () => {\n    it('should create a new order successfully', async () => {\n      const input = {\n        userId: '789',\n        items: [{ productId: 'prod-789', quantity: 2 }]\n      };\n\n      const order = await resolvers.Mutation.createOrder({}, input, context);\n\n      expect(order).toBeDefined();\n      expect(order.id).toBeDefined();\n      expect(order.userId).toBe('789');\n      expect(order.status).toBe('PENDING');\n      expect(order.totalAmount).toBeGreaterThan(0);\n      expect(order.items.length).toBe(1);\n      expect(order.items[0].productId).toBe('prod-789');\n      expect(order.items[0].quantity).toBe(2);\n      expect(order.items[0].price).toBeDefined();\n    });\n  });\n\n  describe('DataLoader functionality', () => {\n    it('should batch multiple order requests', async () => {\n      const orderIds = ['order-456', 'order-457'];\n      const orders = await Promise.all(orderIds.map(id => loaders.orderLoader.load(id)));\n\n      expect(orders.length).toBe(2);\n      expect(orders[0].id).toBe('order-456');\n      expect(orders[1].id).toBe('order-457');\n    });\n\n    it('should batch multiple shipping info requests', async () => {",
